INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText`, `FemaleText`, `VerifiedBuild`) VALUES
(1320, 'koKR', 'Nareszcie wolny z tej nędznej celi! Pozwólcie, że zaprowadzę was na dziedziniec...', '', 0),
(1321, 'koKR', 'Zaiste, odwagi wam nie brakuje, skoro chcecie stawić czoła okropieństwom, które czają się za tymi drzwiami.', '', 0),
(1323, 'koKR', 'No i proszę!', '', 0),
(1324, 'koKR', 'Powodzenia z Arugalem. Muszę teraz szybko wracać do Hadreca.', '', 0),
(1328, 'koKR', 'Najwyższy czas, żeby ktoś zabił tego nędznika.', '', 0),
(1329, 'koKR', 'Choć raz się z tobą zgadzam... szumowino.', '', 0),
(1331, 'koKR', 'Chodźcie za mną, otworzę wam drzwi na dziedziniec.', '', 0),
(1332, 'koKR', 'Mam akurat zaklęcie, które otworzy te drzwi. Szkoda, że drzwi cel nie były zamknięte równie niedbale.', '', 0),
(1334, 'koKR', 'Proszę bardzo! Otwarte na oścież. Powodzenia w pokonaniu tego, co czeka dalej. Muszę natychmiast złożyć raport Kirin Torowi!', '', 0),
(1435, 'koKR', 'Kto śmie wchodzić w drogę Synom Arugala?', '', 0),
(1456, 'koKR', 'Zmieniłem zdanie, wierni słudzy, nie musicie prowadzić więźnia aż do mojej pracowni. Rozprawię się z nim tu i teraz.', '', 0),
(2801, 'koKR', 'Nareszcie! W końcu jestem wolny z tej celi!$b$bKirin Tor wysłał mnie z Dalaranu, żebym sprawdził postępy Arugala w pracy z nieumarłymi tu, w Srebrzystym Borze. Nie wiedzieliśmy, że czarodziej postradał zmysły.$b$bMuszę natychmiast donieść o tym bałaganie! Ale zanim odejdę, pozwól, że zdejmę magiczną blokadę z drzwi na dziedziniec.$b$b$GPokonałeś:Pokonałaś; Rethilgore\'a, więc może przetrwasz to, co czeka dalej...', '', 0),
(2802, 'koKR', 'Otwórz, proszę, drzwi na dziedziniec.', 'Otwórz, proszę, drzwi na dziedziniec.', 0),
(2803, 'koKR', 'Nareszcie! Ktoś, kto uwolni mnie z tej celi!$b$bNajwyższy egzekutor Hadrec wysłał nas, żebyśmy zebrali informacje o twierdzy i mogli opracować plan, jak raz na zawsze obalić Arugala.$b$bAle stary czarodziej ma w zanadrzu wiele sztuczek i wykryła nas magiczna osłona. Mnie wtrącono do tego lochu. Vincent nie miał tyle szczęścia.$b$bMuszę natychmiast wrócić do Hadreca i zdać mu raport. Ale najpierw otworzę ci wytrychem zamek w drzwiach na dziedziniec. Może spróbujesz szczęścia z wrogami, którzy czają się dalej.', '', 0),
(5680, 'koKR', 'Vincent! Ty i tobie podobne nędzne kreatury nie zdołacie przepędzić mnie i moich synów, tak jak nie zdołały tego żałosne resztki Kirin Toru.', '', 0),
(5681, 'koKR', 'Skoro nie chcesz służyć mojemu Panu mieczem i wiedzą o jego wrogach...', '', 0),
(5682, 'koKR', '...to twoje gnijące szczątki posłużą MNIE jako przestroga, co spotyka tych, którzy są na tyle głupi, by wtargnąć do mojej domeny!\n', '', 0),
(6115, 'koKR', 'Ty także będziesz służyć!', '', 0),
(6116, 'koKR', 'Kolejny pada!', '', 0),
(6535, 'koKR', 'Uwolnijcie swój gniew!', '', 0),
(14391, 'koKR', 'Trzymaj się ode mnie z daleka! Nie wiadomo, kiedy choroba znów mnie opanuje.$B$BPo prostu zostaw mnie w spokoju, zanim to się powtórzy.', '', 0),
(48821, 'koKR', 'Natychmiast opuśćcie to przeklęte miejsce!', '', 0),
(48826, 'koKR', 'Intruzi w twierdzy! Do broni!', '', 0),
(48829, 'koKR', 'Nasza czujność jest wieczna...', '', 0);
